using System;using System.Diagnostics;using System.IO;using System.Net;using System.Windows.Forms;
internal static class BuiltinDownloads {
    public static string Ensure(WallpaperEntry entry,string state,Action<string> progress){
        var asset=entry.Remote;if(asset==null||String.IsNullOrEmpty(asset.file)||asset.file!=Path.GetFileName(asset.file)||asset.file.IndexOfAny(new[]{'/','\\',':'})>=0||!SoftwareUpdate.Digest(asset.sha256)||asset.bytes<1||asset.bytes>2L*1024*1024*1024||WallpaperLibrary.MediaKind(asset.file)!="video")throw new InvalidDataException("内置视频下载清单无效。");SoftwareUpdate.ReleaseUri(asset.url);
        string folder=Path.Combine(state,"builtin-wallpapers");Directory.CreateDirectory(folder);string target=Path.Combine(folder,asset.file),old=Path.Combine(Path.GetDirectoryName(entry.Path),asset.file);
        foreach(string existing in new[]{target,old})if(File.Exists(existing)&&new FileInfo(existing).Length==asset.bytes&&SoftwareUpdate.Hash(existing).Equals(asset.sha256,StringComparison.OrdinalIgnoreCase))return existing;
        string temporary=target+".partial-"+Guid.NewGuid().ToString("N");try{ServicePointManager.SecurityProtocol|=SecurityProtocolType.Tls12;var request=(HttpWebRequest)WebRequest.Create(asset.url);request.UserAgent="CodexHub-Wallpaper";request.Timeout=request.ReadWriteTimeout=30000;using(var response=request.GetResponse())using(var source=response.GetResponseStream())using(var output=File.Create(temporary)){byte[] buffer=new byte[65536];long total=0,last=-250;int count;var clock=Stopwatch.StartNew();while((count=source.Read(buffer,0,buffer.Length))>0){total+=count;if(total>asset.bytes)throw new InvalidDataException("壁纸下载大小超出清单。");output.Write(buffer,0,count);if(clock.ElapsedMilliseconds-last>=250){last=clock.ElapsedMilliseconds;progress("正在从 GitHub 下载内置视频 "+(total*100/asset.bytes)+"% · 宠物继续运行");}}if(total!=asset.bytes)throw new InvalidDataException("壁纸下载不完整。");}if(!SoftwareUpdate.Hash(temporary).Equals(asset.sha256,StringComparison.OrdinalIgnoreCase))throw new InvalidDataException("壁纸校验失败。");if(File.Exists(target))File.Replace(temporary,target,null);else File.Move(temporary,target);return target;}finally{if(File.Exists(temporary))File.Delete(temporary);}
    }
}
internal sealed partial class Manager {
    bool downloadingBuiltin;
    void DownloadBuiltin(WallpaperEntry entry){downloadingBuiltin=true;applyButton.Enabled=false;previewHint.Text="正在准备完整视频，已有原片会直接复用…";ImportWork.Start(delegate{try{string path=BuiltinDownloads.Ensure(entry,stateDirectory,message=>Ui(delegate{previewHint.Text=message;}));Ui(delegate{downloadingBuiltin=false;entry.Path=path;entry.Kind="video";applyButton.Enabled=selected!=null&&selected.Available;if(selected==entry){CancelPreview();Run("Apply");}else previewHint.Text="视频已下载，可重新选择后应用。";});}catch(Exception error){Ui(delegate{downloadingBuiltin=false;applyButton.Enabled=selected!=null&&selected.Available;previewHint.Text="视频准备未完成："+error.Message;});}});}
}
